/* eslint-disable @stencil-community/required-jsdoc */
import { Component, ComponentInterface, Element, Host, Prop, h, Fragment } from '@stencil/core';
import { DatePickerViewMode } from '../../../types';
import type { Dayjs } from 'dayjs';
import { getViewModeConfig } from '../../../view-modes';
import {
  addPeriodToDate,
  dayjsToNativeDate,
  getDecadeLabelOfYear,
  getLocalizedMonth,
  isYearFirst,
} from '../../../utils';
import { globalConfigStore } from '@src/shared/stores';
import { DateGridSharedContract } from '../types';
import {
  KsIconChevronLeft,
  KsIconChevronRight,
  KsIconDoubleChevronLeft,
  KsIconDoubleChevronRight,
} from '@fe-infra/keystone-icons-stencil';

const prefix = 'date-grid-header';

@Component({
  tag: 'ks-date-time-picker-date-grid-header',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDateTimePickerDateGridHeader
  implements
    Omit<DateGridSharedContract, 'isRange' | 'value' | 'now' | 'selectionPhase' | 'disabledDate' | 'handleValueChange'>,
    ComponentInterface
{
  @Element() el!: HTMLKsDateTimePickerDateGridHeaderElement;

  @Prop() viewDate!: Dayjs;
  @Prop() viewMode!: DatePickerViewMode;
  @Prop() availableViewModes!: DatePickerViewMode[];

  @Prop() layoutMode!: 'inline-start' | 'inline-end' | 'standalone';

  @Prop() handleViewChange!: (viewDate: Dayjs, viewMode: DatePickerViewMode) => void;

  private get locale() {
    return globalConfigStore.state.locale;
  }

  private get viewModeConfig() {
    return getViewModeConfig(this.viewMode);
  }

  private navigateHandler = (value: number, period: 'month' | 'yearOrDecade') => () => {
    if (this.layoutMode === 'inline-end') {
      if (period === 'yearOrDecade') {
        const startViewDate = addPeriodToDate(this.viewDate, -1, this.viewModeConfig.period);
        if (this.viewModeConfig.header.showDecade) {
          this.handleViewChange(addPeriodToDate(startViewDate, value, 'decade'), this.viewMode);
        } else {
          this.handleViewChange(addPeriodToDate(startViewDate, value, 'year'), this.viewMode);
        }
      } else {
        // for the DateGrid placed inline-end, its viewDate is already the next period of the `viewDate` of DatePicker
        this.handleViewChange(this.viewDate, this.viewMode);
      }
    } else {
      if (period === 'yearOrDecade') {
        if (this.viewModeConfig.header.showDecade) {
          this.handleViewChange(addPeriodToDate(this.viewDate, value, 'decade'), this.viewMode);
        } else {
          this.handleViewChange(addPeriodToDate(this.viewDate, value, 'year'), this.viewMode);
        }
      } else {
        this.handleViewChange(addPeriodToDate(this.viewDate, value, 'month'), this.viewMode);
      }
    }
  };
  private handleNavigateToLastYearOrDecade = this.navigateHandler(-1, 'yearOrDecade');
  private handleNavigateToNextYearOrDecade = this.navigateHandler(1, 'yearOrDecade');
  private handleNavigateToLastMonth = this.navigateHandler(-1, 'month');
  private handleNavigateToNextMonth = this.navigateHandler(1, 'month');

  private get yearClickable() {
    return this.availableViewModes.includes('yearInDecade');
  }
  private handleYearClick = () => {
    this.handleViewChange(this.viewDate, 'yearInDecade');
  };

  private get monthClickable() {
    return this.availableViewModes.includes('monthInYear');
  }
  private handleMonthClick = () => {
    this.handleViewChange(this.viewDate, 'monthInYear');
  };

  render() {
    const { showDecade, showYear, showMonth } = this.viewModeConfig.header;

    return (
      <Host>
        <div class={prefix}>
          <div
            class={{
              [`${prefix}__controls`]: true,
              [`${prefix}__controls--hidden`]: this.layoutMode === 'inline-end',
            }}
          >
            {(showDecade || showYear) && (
              <ks-icon-button
                size="xs"
                variant="text"
                onClick={this.handleNavigateToLastYearOrDecade}
                data-testid="date-grid-header-index-h61LWF"
              >
                <KsIconDoubleChevronLeft size="14" class={`${prefix}__controls-button`} />
              </ks-icon-button>
            )}

            {showMonth && (
              <ks-icon-button
                size="xs"
                variant="text"
                onClick={this.handleNavigateToLastMonth}
                data-testid="date-grid-header-index-7uEm7r"
              >
                <KsIconChevronLeft size="14" class={`${prefix}__controls-button`} />
              </ks-icon-button>
            )}
          </div>

          <div class={`${prefix}__labels`}>
            {showDecade && <div>{getDecadeLabelOfYear(this.viewDate.year())}</div>}

            {(() => {
              const yearElement = showYear ? (
                this.yearClickable ? (
                  <button
                    class={{
                      [`${prefix}__labels-part--clickable`]: this.yearClickable,
                    }}
                    onClick={this.handleYearClick}
                    data-testid="date-grid-header-index-4w9K37"
                  >
                    {this.viewDate.year()}
                  </button>
                ) : (
                  <div>{this.viewDate.year()}</div>
                )
              ) : null;

              const monthElement = showMonth ? (
                this.monthClickable ? (
                  <button
                    class={{
                      [`${prefix}__labels-part--clickable`]: this.monthClickable,
                    }}
                    onClick={this.handleMonthClick}
                    data-testid="date-grid-header-index-mSJSJe"
                  >
                    {getLocalizedMonth(dayjsToNativeDate(this.viewDate), this.locale)}
                  </button>
                ) : (
                  <div>{getLocalizedMonth(dayjsToNativeDate(this.viewDate), this.locale)}</div>
                )
              ) : null;

              const _isYearFirst = isYearFirst(this.locale);
              return (
                <Fragment>
                  {_isYearFirst && yearElement}
                  {monthElement}
                  {!_isYearFirst && yearElement}
                </Fragment>
              );
            })()}
          </div>

          <div
            class={{
              [`${prefix}__controls`]: true,
              [`${prefix}__controls--hidden`]: this.layoutMode === 'inline-start',
            }}
          >
            {showMonth && (
              <ks-icon-button
                size="xs"
                variant="text"
                onClick={this.handleNavigateToNextMonth}
                data-testid="date-grid-header-index-nspxMo"
              >
                <KsIconChevronRight size="14" class={`${prefix}__controls-button`} />
              </ks-icon-button>
            )}

            {(showDecade || showYear) && (
              <ks-icon-button
                size="xs"
                variant="text"
                onClick={this.handleNavigateToNextYearOrDecade}
                data-testid="date-grid-header-index-j9HUXB"
              >
                <KsIconDoubleChevronRight size="14" class={`${prefix}__controls-button`} />
              </ks-icon-button>
            )}
          </div>
        </div>
      </Host>
    );
  }
}
